import { describe, it, expect, vi, beforeEach } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

vi.mock("../logger", () => ({
  log: {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    success: vi.fn(),
    path: (p: string) => p,
    code: (c: string) => c,
  },
}));

import { resolveSlidevBin } from "../buildRunner";

describe("resolveSlidevBin", () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "buildrunner-"));
  });

  it("finds slidev binary in node_modules/.bin", () => {
    const binName = process.platform === "win32" ? "slidev.cmd" : "slidev";
    const binDir = path.join(tmpDir, "node_modules", ".bin");
    fs.mkdirSync(binDir, { recursive: true });
    fs.writeFileSync(path.join(binDir, binName), "#!/bin/sh\necho slidev", { mode: 0o755 });

    const result = resolveSlidevBin(tmpDir);
    expect(result).toBe(path.join(binDir, binName));
  });

  it("walks up directory tree for monorepo hoisting", () => {
    const binName = process.platform === "win32" ? "slidev.cmd" : "slidev";
    const rootBinDir = path.join(tmpDir, "node_modules", ".bin");
    fs.mkdirSync(rootBinDir, { recursive: true });
    fs.writeFileSync(path.join(rootBinDir, binName), "#!/bin/sh\necho slidev", { mode: 0o755 });

    const childDir = path.join(tmpDir, "packages", "my-app");
    fs.mkdirSync(childDir, { recursive: true });

    const result = resolveSlidevBin(childDir);
    expect(result).toBe(path.join(rootBinDir, binName));
  });

  it("falls back to binary name when not found", () => {
    const binName = process.platform === "win32" ? "slidev.cmd" : "slidev";
    const result = resolveSlidevBin(tmpDir);
    expect(result).toBe(binName);
  });
});
